from pathlib import Path
exec((Path(__file__).resolve().parent/'run.py').read_text().split('\ntry:')[0])
BASE=R;R=BASE/'audit';R.mkdir(exist_ok=True);D=R/'data';D.mkdir(exist_ok=True)
LIB['candidate']=BASE/'candidate4/src/perl';BIN['candidate']=LIB['candidate']
try:
 save('preparing');begin=time.monotonic()
 # Fix only autogenerated source-header dates identically in all three versions.
 # No scientific operation in these tools calls time(). GNU time remains real.
 (D/'FixedHeaderClock.pm').write_text('package FixedHeaderClock; BEGIN { *CORE::GLOBAL::time = sub () { 1795737600 }; } 1;\n')
 ENV['PERL5OPT']='-MFixedHeaderClock'
 for k in LIB:LIB[k]=Path(str(LIB[k])) # PERL5LIB below needs the additional clock search directory.
 import sys
 os.environ['PERL5LIB']=str(D)
 # runrow explicitly sets PERL5LIB, so put the test clock in Perl's normal -I path.
 ENV['PERL5OPT']='-I'+str(D)+' -MFixedHeaderClock'
 src=Path('/jobtmp/zliu328/nuvcftools-parallel-ld-20261126/data/cohort500.vcf.gz')
 srcall=Path('/jobtmp/zliu328/nuvcftools-expanded-20261121/data/cohort_all.vcf.gz')
 plain=D/'cohort500.vcf'
 import shutil
 with gzip.open(src,'rb') as inp,plain.open('wb') as out:shutil.copyfileobj(inp,out)
 with plain.open('rb') as inp,(D/'windows.vcf').open('wb') as out:
  for line in inp:out.write(line.replace(b'\n',b'\r\n'))
 names=subprocess.check_output(['bcftools','query','-l',str(src)],text=True).splitlines()
 sexes=D/'sexes.txt';sexes.write_text(''.join(n+' M\n' for n in names))
 # Default chr22 ploidy is unchanged: label as pass-through, not conversion.
 exons=Path('/jobtmp/zliu328/nuvcftools-expanded-20261121/data/windows.bed')
 # A coordinate interval is an explicit analysis region, not an exon annotation.
 regions=D/'region.tsv';regions.write_text('22\t20000001\t21000000\n')
 # Overlapping consecutive blocks retain original GT, PQ and sample ordering.
 for name,region in [('left','22:20000001-20600000'),('right','22:20400000-21000000')]:
  f=D/(name+'.vcf.gz')
  subprocess.run(['bcftools','view','--no-version','-t',region,'-Oz','-o',str(f),str(src)],check=True)
  subprocess.run(['tabix','-p','vcf',str(f)],check=True)
 (R/'preparation.json').write_text(json.dumps(dict(seconds=time.monotonic()-begin,excluded=True,header_clock_epoch=1795737600,input_sha256=hashlib.sha256(src.read_bytes()).hexdigest()),indent=2))
 # New code must also match on successful rich FORMAT/version conversion.
 fixture=BASE/'reference2/controls-before/input.vcf'
 snps=BASE/'reference2/data/snps.vcf.gz'
 runrow('phase-overlap-500','vcf-phased-join',['-o','-',str(D/'left.vcf.gz'),str(D/'right.vcf.gz')])
 runrow('fill-an-ac-500','fill-an-ac',[],src,True)
 runrow('fix-ploidy-pass-through-500','vcf-fix-ploidy',['-s',str(sexes)],src,True)
 runrow('tstv-500','vcf-tstv',[],src,True)
 runrow('indel-stats-region-500','vcf-indel-stats',['-e',str(regions)],src,True)
 runrow('fix-newlines-500','vcf-fix-newlines',[],D/'windows.vcf')
 # Exercise the existing GNU-sort parallel setting in a four-core allocation.
 runrow('sort-parallel4-2504','vcf-sort',['-p','4'],srcall,True)
 fa=BASE/'reference2/data/GRCh37.22.fa';snippet=D/'snippet.fa'
 with snippet.open('wb') as out:subprocess.run(['samtools','faidx',str(fa),'22:20000001-21000000'],stdout=out,check=True)
 runrow('consensus-sample-500','vcf-consensus',['-s',names[0],str(snps)],snippet)
 save('complete')
except Exception:
 save('failed');(R/'failure.txt').write_text(traceback.format_exc());raise
